            {
                pos = tagClose > 0 ? tagClose : pos + 1;
            }

            if (!string.IsNullOrWhiteSpace(title) || !string.IsNullOrWhiteSpace(snippet))
            {
                count++;
                results.AppendLine($"Result {count}: {title}");
                if (!string.IsNullOrWhiteSpace(href))
                    results.AppendLine($"  URL: {href}");
                if (!string.IsNullOrWhiteSpace(snippet))
                    results.AppendLine($"  Snippet: {snippet}");
                results.AppendLine();
            }
        }

