+// --- Agent runner ---
+
+public sealed class ResearchAgentRunner(
+    IChatClient chatClient,
+    ResearchTools tools,
+    ILoggerFactory loggerFactory)
+{
+    public async Task ResearchAsync(string topic)
+    {
+        var agent = new ChatClientAgent(
+            chatClient,
+            new ChatClientAgentOptions
+            {
+                Name = "ResearchAgent",
+                Description = "An AI research assistant that searches the web and takes notes.",
+                ChatOptions = new ChatOptions
+                {
+                    Temperature = 0f,
+                    MaxOutputTokens = 4096,
+                    Tools = [
+                        AIFunctionFactory.Create(tools.SearchWeb),
+                        AIFunctionFactory.Create(tools.AddNote),
+                        AIFunctionFactory.Create(tools.GetNotes),
+                    ],
+                },
+            },
+            loggerFactory);
+
+        var session = await agent.CreateSessionAsync();
+        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
+        {
+            Temperature = 0f,
+        });
+
+        var systemPrompt = $"""
+            You are a research agent. Your goal is to thoroughly research the following topic:
+
+            **{topic}**
+
+            Follow these steps:
+            1. Search the web for relevant information using different queries (at least 2-3 searches).
+            2. For each useful finding, use AddNote to save a concise note with the source URL.
+            3. After gathering enough information, use GetNotes to review all your notes.
+            4. Finally, provide a comprehensive summary of your findings, citing sources.
+
+            Be thorough but concise. Focus on the most important and recent information.
+            """;
+
+        Console.WriteLine($"\n🔍 Researching: {topic}\n");
+
+        var response = await agent.RunAsync(
+            [new ChatMessage(ChatRole.System, systemPrompt),
+             new ChatMessage(ChatRole.User, $"Research this topic: {topic}")],
+            session,
+            runOptions);
+
+        Console.WriteLine("\n📋 Research Summary:");
+        Console.WriteLine(new string('─', 60));
+        Console.WriteLine(response.Message.Text);
+        Console.WriteLine(new string('─', 60));
+
+        var notes = tools.GetAllNotes();
+        if (notes.Count > 0)
+        {
+            Console.WriteLine($"\n📝 {notes.Count} note(s) saved during research:");
+            for (int i = 0; i < notes.Count; i++)
+            {
+                Console.WriteLine($"  {i + 1}. [{notes[i].Source}] {notes[i].Content}");
+            }
+        }
+    }
+}
+
+// --- Tools ---
+
+public sealed class ResearchTools
+{
+    private readonly List<ResearchNote> _notes = [];
+    private readonly HttpClient _httpClient = new()
+    {
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
+    public async Task<string> SearchWeb(
+        [Description("The search query to look up")] string query)
+    {
+        Console.WriteLine($"  🌐 Searching: \"{query}\"");
+
+        try
+        {
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
+
+            using var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.UserAgent.ParseAdd(
+                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
+
+            using var response = await _httpClient.SendAsync(request);
+            response.EnsureSuccessStatusCode();
+            var html = await response.Content.ReadAsStringAsync();
+
+            return ParseSearchResults(html, maxResults: 5);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
+
+    [Description("Save a research note with content and source attribution.")]
+    public string AddNote(
+        [Description("The content of the note")] string content,
+        [Description("The source URL or reference")] string source)
+    {
+        _notes.Add(new ResearchNote(content, source));
+        Console.WriteLine($"  📝 Note saved: {Truncate(content, 60)}");
+        return $"Note #{_notes.Count} saved successfully.";
+    }
+
+    [Description("Retrieve all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes have been saved yet.";
+        }
+
+        var sb = new StringBuilder();
+        for (int i = 0; i < _notes.Count; i++)
+        {
+            sb.AppendLine($"Note {i + 1}: {_notes[i].Content}");
+            sb.AppendLine($"  Source: {_notes[i].Source}");
+        }
+
+        return sb.ToString();
+    }
+
+    public IReadOnlyList<ResearchNote> GetAllNotes() => _notes.AsReadOnly();
+
+    private static string ParseSearchResults(string html, int maxResults)
+    {
+        var results = new StringBuilder();
+        int count = 0;
+
+        // Extract result snippets from DuckDuckGo HTML response
+        var snippetMarker = "class=\"result__snippet\"";
+        var titleMarker = "class=\"result__a\"";
+        int pos = 0;
+
+        while (count < maxResults && pos < html.Length)
+        {
+            int titleStart = html.IndexOf(titleMarker, pos, StringComparison.Ordinal);
+            if (titleStart < 0) break;
+
+            // Extract title text
+            int tagEnd = html.IndexOf('>', titleStart);
+            int tagClose = html.IndexOf('<', tagEnd + 1);
+            string title = tagEnd >= 0 && tagClose > tagEnd
+                ? StripHtml(html[(tagEnd + 1)..tagClose]).Trim()
+                : "";
+
+            // Extract href
+            string href = "";
+            int hrefStart = html.LastIndexOf("href=\"", titleStart, Math.Min(titleStart, 200), StringComparison.Ordinal);
+            if (hrefStart >= 0)
+            {
+                hrefStart += 6;
+                int hrefEnd = html.IndexOf('"', hrefStart);
+                if (hrefEnd > hrefStart)
+                    href = html[hrefStart..hrefEnd];
+            }
+
+            // Extract snippet
+            int snippetStart = html.IndexOf(snippetMarker, titleStart, StringComparison.Ordinal);
+            string snippet = "";
+            if (snippetStart >= 0)
+            {
+                int sTagEnd = html.IndexOf('>', snippetStart);
+                int sTagClose = html.IndexOf("</", sTagEnd + 1, StringComparison.Ordinal);
+                if (sTagEnd >= 0 && sTagClose > sTagEnd)
+                    snippet = StripHtml(html[(sTagEnd + 1)..sTagClose]).Trim();
+                pos = sTagClose;
+            }
+            else
+            {
+                pos = tagClose > 0 ? tagClose : pos + 1;
+            }
+
+            if (!string.IsNullOrWhiteSpace(title) || !string.IsNullOrWhiteSpace(snippet))
+            {
+                count++;
+                results.AppendLine($"Result {count}: {title}");
+                if (!string.IsNullOrWhiteSpace(href))
+                    results.AppendLine($"  URL: {href}");
+                if (!string.IsNullOrWhiteSpace(snippet))
+                    results.AppendLine($"  Snippet: {snippet}");
+                results.AppendLine();
+            }
+        }
+
+        return count > 0
+            ? results.ToString()
+            : "No results found. Try rephrasing the query.";
+    }
+
+    private static string StripHtml(string html)
+    {
+        var sb = new StringBuilder(html.Length);
+        bool inTag = false;
+        foreach (char c in html)
+        {
+            if (c == '<') { inTag = true; continue; }
+            if (c == '>') { inTag = false; continue; }
+            if (!inTag) sb.Append(c);
+        }
+
+        return System.Net.WebUtility.HtmlDecode(sb.ToString());
+    }
+
+    private static string Truncate(string text, int maxLength) =>
+        text.Length <= maxLength ? text : text[..maxLength] + "...";
+}
+
+public record ResearchNote(string Content, string Source);

