120. public sealed class ResearchTools
121. {
122.     private readonly List<ResearchNote> _notes = [];
123.     private readonly HttpClient _httpClient = new()
124.     {
125.         Timeout = TimeSpan.FromSeconds(15),
126.     };
127. 
128.     [Description("Search the web for information on a query. Returns a list of search result snippets.")]
129.     public async Task<string> SearchWeb(
130.         [Description("The search query to look up")] string query)
131.     {
132.         Console.WriteLine($"  🌐 Searching: \"{query}\"");
133. 
134.         try
135.         {
136.             var encoded = Uri.EscapeDataString(query);
137.             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
138. 
139.             using var request = new HttpRequestMessage(HttpMethod.Get, url);
140.             request.Headers.UserAgent.ParseAdd(
141.                 "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
142. 
143.             using var response = await _httpClient.SendAsync(request);
144.             response.EnsureSuccessStatusCode();
145.             var html = await response.Content.ReadAsStringAsync();
146. 
147.             return ParseSearchResults(html, maxResults: 5);
148.         }
149.         catch (Exception ex)
150.         {
151.             return $"Search failed: {ex.Message}. Try a different query.";
152.         }
153.     }
154. 
155.     [Description("Save a research note with content and source attribution.")]
156.     public string AddNote(
157.         [Description("The content of the note")] string content,
158.         [Description("The source URL or reference")] string source)
159.     {
160.         _notes.Add(new ResearchNote(content, source));
161.         Console.WriteLine($"  📝 Note saved: {Truncate(content, 60)}");
162.         return $"Note #{_notes.Count} saved successfully.";
163.     }
164. 
165.     [Description("Retrieve all saved research notes.")]
166.     public string GetNotes()
167.     {
168.         if (_notes.Count == 0)
169.         {
170.             return "No notes have been saved yet.";
171.         }
172. 
173.         var sb = new StringBuilder();
174.         for (int i = 0; i < _notes.Count; i++)
175.         {
176.             sb.AppendLine($"Note {i + 1}: {_notes[i].Content}");
177.             sb.AppendLine($"  Source: {_notes[i].Source}");
178.         }
179. 
180.         return sb.ToString();
181.     }
182. 
183.     public IReadOnlyList<ResearchNote> GetAllNotes() => _notes.AsReadOnly();
184. 
185.     private static string ParseSearchResults(string html, int maxResults)
186.     {
187.         var results = new StringBuilder();
188.         int count = 0;
189. 
190.         // Extract result snippets from DuckDuckGo HTML response
191.         var snippetMarker = "class=\"result__snippet\"";
192.         var titleMarker = "class=\"result__a\"";
193.         int pos = 0;
194. 
195.         while (count < maxResults && pos < html.Length)
196.         {
197.             int titleStart = html.IndexOf(titleMarker, pos, StringComparison.Ordinal);
198.             if (titleStart < 0) break;
199. 
200.             // Extract title text
201.             int tagEnd = html.IndexOf('>', titleStart);
202.             int tagClose = html.IndexOf('<', tagEnd + 1);
203.             string title = tagEnd >= 0 && tagClose > tagEnd
204.                 ? StripHtml(html[(tagEnd + 1)..tagClose]).Trim()
205.                 : "";
206. 
207.             // Extract href
208.             string href = "";
209.             int hrefStart = html.LastIndexOf("href=\"", titleStart, Math.Min(titleStart, 200), StringComparison.Ordinal);
210.             if (hrefStart >= 0)
211.             {
212.                 hrefStart += 6;
213.                 int hrefEnd = html.IndexOf('"', hrefStart);
214.                 if (hrefEnd > hrefStart)
215.                     href = html[hrefStart..hrefEnd];
216.             }
217. 
218.             // Extract snippet
219.             int snippetStart = html.IndexOf(snippetMarker, titleStart, StringComparison.Ordinal);
220.             string snippet = "";
221.             if (snippetStart >= 0)
222.             {
223.                 int sTagEnd = html.IndexOf('>', snippetStart);
224.                 int sTagClose = html.IndexOf("</", sTagEnd + 1, StringComparison.Ordinal);
225.                 if (sTagEnd >= 0 && sTagClose > sTagEnd)
226.                     snippet = StripHtml(html[(sTagEnd + 1)..sTagClose]).Trim();
227.                 pos = sTagClose;
228.             }
229.             else
230.             {
231.                 pos = tagClose > 0 ? tagClose : pos + 1;
232.             }
233. 
234.             if (!string.IsNullOrWhiteSpace(title) || !string.IsNullOrWhiteSpace(snippet))
235.             {
236.                 count++;
237.                 results.AppendLine($"Result {count}: {title}");
238.                 if (!string.IsNullOrWhiteSpace(href))
239.                     results.AppendLine($"  URL: {href}");
240.                 if (!string.IsNullOrWhiteSpace(snippet))
241.                     results.AppendLine($"  Snippet: {snippet}");
242.                 results.AppendLine();
243.             }
244.         }
245. 
246.         return count > 0
247.             ? results.ToString()
248.             : "No results found. Try rephrasing the query.";
249.     }
250. 
251.     private static string StripHtml(string html)
252.     {
253.         var sb = new StringBuilder(html.Length);
254.         bool inTag = false;
255.         foreach (char c in html)
256.         {
257.             if (c == '<') { inTag = true; continue; }
258.             if (c == '>') { inTag = false; continue; }
259.             if (!inTag) sb.Append(c);
260.         }
261. 
262.         return System.Net.WebUtility.HtmlDecode(sb.ToString());
263.     }
264. 
265.     private static string Truncate(string text, int maxLength) =>
266.         text.Length <= maxLength ? text : text[..maxLength] + "...";
267. }
268. 
